	{
		this(componentId, Map.of());
	}

	public static final TargetWidget[] CONTAINERS =
		{
			CLASSIC_MAP_CONTAINER, MODERN_MAP_CONTAINER,
			CLASSIC_ORBS_CONTAINER, MODERN_ORBS_CONTAINER,
