			if (manager.isFixedMode())
			{
				return 50;
			}

			if (manager.isStoreOrbDisabled())
			{
				y = Layout.Original.STORE_ORB_Y;
			}

			return y;
		}

		if (manager.getCurrentLayout().isVertical())
		{
			y = slotManager.applyHiddenYOffset(Orbs.ACTIVITY_ORB_CONTAINER, y);
		}

		return y;
	}
